import{_ as n,o as i,c as t,a2 as r}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"Mechanismus der technologischen Öffnung und des Teilens","description":"","frontmatter":{},"headers":[],"relativePath":"de/69-技术开放与共享机制.md","filePath":"de/69-技术开放与共享机制.md"}'),s={name:"de/69-技术开放与共享机制.md"};function o(h,e,l,d,g,u){return i(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="mechanismus-der-technologischen-offnung-und-des-teilens" tabindex="-1">Mechanismus der technologischen Öffnung und des Teilens <a class="header-anchor" href="#mechanismus-der-technologischen-offnung-und-des-teilens" aria-label="Permalink to &quot;Mechanismus der technologischen Öffnung und des Teilens&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Punkt</th><th>Inhalt</th></tr></thead><tbody><tr><td>Dokumentennummer</td><td>69</td></tr><tr><td>Modul</td><td>Technologie- und Energiesystem</td></tr><tr><td>Kernschlüsselwörter</td><td>Technologische Öffnung, Wissensaustausch, Open-Source-Gesetze, Technologieverbreitung, Kartellverbot</td></tr></tbody></table><h2 id="i-kernkonzept-der-technologischen-offnung" tabindex="-1">I. Kernkonzept der technologischen Öffnung <a class="header-anchor" href="#i-kernkonzept-der-technologischen-offnung" aria-label="Permalink to &quot;I. Kernkonzept der technologischen Öffnung&quot;">​</a></h2><p>Der Mechanismus der technologischen Öffnung und des Teilens der Anker-Symbiose-Zivilisation ist die konkrete Verkörperung des Grundprogramms &quot;Mehr Arbeit, mehr Gewinn; selbst wachsen; jeder hat einen Weg; gemeinsamer Fortschritt aller Rassen&quot; im technologischen Bereich. Sein Kernkonzept ist: Technologisches Wissen sollte als Produkt der kollektiven Evolution der gesamten Zivilisation von der gesamten Zivilisation geteilt werden; Technologiemonopole und Wissensbarrieren sind Überreste des räuberischen Systems im technologischen Bereich und müssen durch institutionelles Design beseitigt werden.</p><p>Die technologische Öffnung bedeutet nicht, den Beitrag der Technologieforscher zu leugnen. Im Gegenteil, die Symbiose-Zivilisation hat einen Technologieanreizmechanismus &quot;Beitrag ist messbar, Nutzen ist nachverfolgbar&quot; etabliert, der sicherstellt, dass die Arbeit der Forscher eine angemessene Vergütung erhält, während gleichzeitig die technologischen Ergebnisse mit der niedrigsten Schwelle allen Wesen zugutekommen können. Das Wesen dieses Mechanismus besteht darin, die Technologie von einem &quot;von wenigen monopolisierten Gut&quot; zu einer &quot;von der gesamten Zivilisation geteilten Infrastruktur&quot; zu wandeln.</p><h2 id="ii-system-der-gestuften-technologischen-offnung" tabindex="-1">II. System der gestuften technologischen Öffnung <a class="header-anchor" href="#ii-system-der-gestuften-technologischen-offnung" aria-label="Permalink to &quot;II. System der gestuften technologischen Öffnung&quot;">​</a></h2><p>Die technologische Öffnung implementiert eine gestufte Öffnung entsprechend dem Risikoniveau und dem Reifegrad:</p><table tabindex="0"><thead><tr><th>Öffnungsstufe</th><th>Anwendbare Technologie</th><th>Öffnungsweise</th><th>Zugangsbedingungen</th></tr></thead><tbody><tr><td>Vollständige Öffnung</td><td>Ausgereifte Technologien der Stufen R0, R1</td><td>Alle technischen Dokumente und Konstruktionszeichnungen werden kostenlos veröffentlicht</td><td>Keine Schwelle, jedes Wesen kann sie erhalten</td></tr><tr><td>Lizenzöffnung</td><td>Ausgereifte Technologien der Stufe R2</td><td>Kernprinzipien werden veröffentlicht, für die technische Umsetzung ist eine Lizenzbeantragung erforderlich</td><td>Muss eine grundlegende Sicherheitsschulung bestehen und sich zur Einhaltung der Nutzungsnormen verpflichten</td></tr><tr><td>Eingeschränkte Öffnung</td><td>Technologien der Stufe R3</td><td>Nur für autorisierte Forschungsinstitute geöffnet, Unterzeichnung eines Sicherheitsabkommens erforderlich</td><td>Muss über einen isolierten Raum der S-Klasse und eine Ethikprüfungsqualifikation verfügen</td></tr><tr><td>Verbotene Öffnung</td><td>Verbotene Technologien der Stufe R4</td><td>Nicht geöffnet</td><td>Vollständiges Verbot</td></tr></tbody></table><p>Für die vollständig geöffneten Technologien hat die Symbiose-Zivilisation die &quot;Open-Source-Gesetzesbibliothek&quot; etabliert — eine technologische Wissensdatenbank, die den Open-Source-Software-Communitys der realen Welt ähnelt. Alle Forscher können ihre technologischen Ergebnisse an die Open-Source-Gesetzesbibliothek übermitteln, die nach Prüfung durch den Technologieausschuss für die gesamte Zivilisation geöffnet wird. Die Technologien in der Open-Source-Gesetzesbibliothek采用 die &quot;Symbiose-Sharing-Lizenz&quot;, die freie Nutzung, Modifikation und Weiterverbreitung erlaubt, aber abgeleitete Werke müssen ebenfalls auf Open-Source-Weise geteilt werden.</p><h2 id="iii-infrastruktur-der-technologieverbreitung" tabindex="-1">III. Infrastruktur der Technologieverbreitung <a class="header-anchor" href="#iii-infrastruktur-der-technologieverbreitung" aria-label="Permalink to &quot;III. Infrastruktur der Technologieverbreitung&quot;">​</a></h2><p>Um sicherzustellen, dass die technologische Öffnung nicht zur Form wird, hat die Symbiose-Zivilisation eine vollständige Infrastruktur für die Technologieverbreitung aufgebaut:</p><ol><li><strong>Technologiebildungssystem</strong>: Im Symbiose-Bildungssystem wird grundlegendes Gesetzesingenieurwissen als Inhalt der Allgemeinbildung gelistet, um sicherzustellen, dass jedes Wesen über die Fähigkeit verfügt, grundlegende Technologien zu verstehen und anzuwenden. Die weiterführende Technologiebildung ist für alle lernbereiten Lernenden kostenlos geöffnet</li><li><strong>Technologieverbreitungsnetzwerk</strong>: Gestützt auf das Kommunikationsnetzwerk zwischen Ebenen wurde eine universelle Technologieverbreitungsplattform aufgebaut, einschließlich Online-Kurse, Technologieforen, virtuelle Labore usw., damit auch Lernende in abgelegenen Ebenen die neuesten technologischen Kenntnisse erhalten können</li><li><strong>Öffentliche Technologieeinrichtungen</strong>: In den Gemeinschaftsankern sind öffentliche Technologielabore und Fertigungsgeräte ausgestattet, jedes Wesen kann sie reservieren und nutzen, um technologisches Wissen in tatsächliche Produkte umzuwandeln</li><li><strong>Technologie-Mentor-System</strong>: Hochqualifizierte Techniker sind verpflichtet, regelmäßig als Technologie-Mentoren zu fungieren und Anfänger zu unterrichten, diese Verpflichtung wird in ihrem Symbiose-Beitragsgrad berücksichtigt</li></ol><h2 id="iv-messung-und-anreiz-des-technologiebeitrags" tabindex="-1">IV. Messung und Anreiz des Technologiebeitrags <a class="header-anchor" href="#iv-messung-und-anreiz-des-technologiebeitrags" aria-label="Permalink to &quot;IV. Messung und Anreiz des Technologiebeitrags&quot;">​</a></h2><p>Die Nachhaltigkeit des Mechanismus der technologischen Öffnung hängt von einem angemessenen System zur Messung und Anreizung von Beiträgen ab:</p><ul><li><strong>Beitragsgradmessung</strong>: Nachdem die von Forschern eingereichten technologischen Ergebnisse in die Open-Source-Gesetzesbibliothek aufgenommen wurden, wird der &quot;Technologiebeitragsgrad&quot; entsprechend ihrem technologischen Wert, ihrem Anwendungsbereich und ihrem abgeleiteten Beitrag berechnet. Der Beitragsgrad ist eine wichtige Grundlage für die Ressourcenverteilung im Mechanismus der gemeinsamen Produktionsverträge</li><li><strong>Prioritäres Nutzungsrecht</strong>: Technologieforscher genießen für einen bestimmten Zeitraum das prioritäre Nutzungsrecht an ihren technologischen Ergebnissen und das Prioritätsrecht für weiterführende Dienste, dürfen jedoch das Verbreitungsrecht der Technologie nicht monopolisieren</li><li><strong>Ehrensystem</strong>: Technologieforschern, die einen bedeutenden Beitrag für die gesamte Zivilisation geleistet haben, werden Ehren wie die &quot;Symbiose-Technologie-Medaille&quot; verliehen, und ihre Leistungen werden in die Technologiegeschichte der Zivilisation aufgenommen</li><li><strong>Nachhaltiger Nutzen</strong>: Für weiterführende Technologieanwendungen, die viel Energie verbrauchen, können Forscher einen angemessenen Anteil an den Anwendungserlösen erhalten, aber der Anteil ist durch die Obergrenze des Kartellverbotsgesetzes beschränkt</li></ul><h2 id="v-kartellverbot-und-technologische-gerechtigkeit" tabindex="-1">V. Kartellverbot und technologische Gerechtigkeit <a class="header-anchor" href="#v-kartellverbot-und-technologische-gerechtigkeit" aria-label="Permalink to &quot;V. Kartellverbot und technologische Gerechtigkeit&quot;">​</a></h2><p>Die Durchführung des Mechanismus der technologischen Öffnung wird durch das Kartellverbotgesetz streng gewährleistet:</p><ul><li>Es ist jeder Organisation oder jedem Einzelnen untersagt, das Verbreitungsrecht von Grundlagentechnologien durch Patentbarrieren, Technologiegeheimnisse usw. zu monopolisieren</li><li>Das &quot;Technologie-Lock&quot;-Verhalten ist verboten, d.h. Nutzer durch absichtliche Schaffung inkompatibler Standards zur Abhängigkeit von bestimmten Technologieanbietern zu zwingen</li><li>Für kritische Infrastrukturtechnologien (wie Anker-Hardware, Energieverteilung, Kommunikation zwischen Ebenen) wird eine obligatorische Öffnung implementiert, und ihre Kernstandards müssen gemeinsam von der gesamten Zivilisation festgelegt werden</li><li>Ein Mechanismus zur Bewertung der technologischen Gerechtigkeit wird etabliert, der regelmäßig den Grad der Ausgewogenheit der Technologieverbreitung bewertet und gezielte Unterstützung für technologisch rückständige Ebenen und Gruppen bereitstellt</li></ul><h2 id="vi-balance-zwischen-technologischer-offnung-und-sicherheit" tabindex="-1">VI. Balance zwischen technologischer Öffnung und Sicherheit <a class="header-anchor" href="#vi-balance-zwischen-technologischer-offnung-und-sicherheit" aria-label="Permalink to &quot;VI. Balance zwischen technologischer Öffnung und Sicherheit&quot;">​</a></h2><p>Zwischen technologischer Öffnung und technologischer Sicherheit ist eine feine Balance erforderlich. Die Vorgehensweise der Symbiose-Zivilisation ist:</p><ul><li>Grundprinzipien und Allgemeinwissen werden vollständig geöffnet, damit mehr Menschen das Wesen der Technologie verstehen und dadurch technologische Risiken besser erkennen können</li><li>Spezifische Parameter und Implementierungsdetails von Hochrisikooperationen werden eingeschränkt geöffnet und nur an Institutionen mit Sicherheitsbedingungen bereitgestellt</li><li>Das Wissen über verbotene Technologien wird streng geheim gehalten, aber die ethische Analyse &quot;warum verboten&quot; ist offen und transparent, damit die gesamte Zivilisation die Bedeutung der Existenz der Grenzen versteht</li><li>Es werden Normen für &quot;verantwortungsvolle Technologieverbreitung&quot; etabliert, Technologieverbreiter sind verpflichtet, gleichzeitig die sichere Nutzungsmethode und die ethischen Grenzen der Technologie zu verbreiten</li></ul><h2 id="schlussfolgerung" tabindex="-1">Schlussfolgerung <a class="header-anchor" href="#schlussfolgerung" aria-label="Permalink to &quot;Schlussfolgerung&quot;">​</a></h2><p>Der Mechanismus der technologischen Öffnung und des Teilens ist eines der wichtigsten Merkmale, die die Anker-Symbiose-Zivilisation von räuberischen Zivilisationen unterscheiden. Im räuberischen System ist die Technologie ein Werkzeug, mit dem die Starken die Schwachen unterdrücken; in der Symbiose-Zivilisation ist die Technologie die Leiter für die gemeinsame Evolution aller Rassen. Durch gestufte Öffnung, Verbreitung der Infrastruktur, angemessene Anreize und kartellverbotliche Gewährleistungen baut die Symbiose-Zivilisation ein Technologie-Ökosystem auf, in dem &quot;Wissen frei fließt, Fähigkeiten allgemein gesteigert werden, Beiträge fair vergütet werden&quot;, was eine kontinuierliche Innovationskraft für die allgemeine Dimensionserhöhung der Zivilisation bereitstellt.</p><h2 id="verwandte-dokumente" tabindex="-1">Verwandte Dokumente <a class="header-anchor" href="#verwandte-dokumente" aria-label="Permalink to &quot;Verwandte Dokumente&quot;">​</a></h2><ul><li>60-Überblick über das Technologiesystem</li><li>68-Technische Ethik und Sicherheitsgrenzen</li><li>47-Kartellverbotgesetz</li></ul>',25)])])}const f=n(s,[["render",o]]);export{c as __pageData,f as default};
